/* Enforce hidden attribute constraint */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b3a4a;
  --card-bg: #e6dfcf;
  --card-border: #3c2a1a;
  --desk-wood: #c68a4c;
  --desk-wood-dark: #8c5826;
  --desk-top: #deb887;
  --chalkboard-bg: #2d5a3f;
  --chalk-text: #f0f7f2;
  --text-dark: #221c16;
  --accent: #d35400;
  --occupied-bg: #879f82;
  --occupied-top: #b5ceb0;
  --occupied-border: #3d5939;
  --focus-ring: #2563eb;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  font-family: "Courier New", Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  color: var(--text-dark);
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.classroom-card {
  background-color: var(--card-bg);
  border: 4px solid var(--card-border);
  box-shadow: 8px 8px 0px #111a24;
  border-radius: 4px;
  width: 100%;
  max-width: 620px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.classroom-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.title {
  font-size: 24px;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--card-border);
}

.chalkboard {
  background-color: var(--chalkboard-bg);
  border: 4px solid #5d4037;
  box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.25);
  color: var(--chalk-text);
  padding: 12px 24px;
  border-radius: 2px;
  text-align: center;
  width: 100%;
}

.chalk-label {
  display: block;
  font-size: 14px;
  text-transform: uppercase;
  opacity: 0.85;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.counter-text {
  font-size: 20px;
  font-weight: bold;
}

.control-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-weight: bold;
  font-size: 16px;
  color: var(--card-border);
}

.input-group {
  display: flex;
  width: 100%;
}

.pixel-input {
  width: 100%;
  padding: 10px 14px;
  font-family: inherit;
  font-size: 16px;
  border: 3px solid var(--card-border);
  background-color: #ffffff;
  color: var(--text-dark);
  outline: none;
}

.pixel-input:focus {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.3);
}

.status-hint {
  font-size: 14px;
  color: #4a3c31;
  min-height: 20px;
}

.classroom-area {
  width: 100%;
}

.grid-container {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.desk-cell {
  position: relative;
  min-height: 84px;
  background-color: var(--desk-wood);
  border: 3px solid var(--desk-wood-dark);
  box-shadow: 3px 3px 0px rgba(0, 0, 0, 0.3);
  border-radius: 2px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  padding: 6px;
  transition: transform 0.05s ease;
  outline: none;
  font-family: inherit;
}

.desk-cell:hover {
  transform: translateY(-2px);
  background-color: #d89b5c;
}

.desk-cell:focus-visible {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px var(--focus-ring);
}

.desk-cell:active {
  transform: translateY(1px);
  box-shadow: 1px 1px 0px rgba(0, 0, 0, 0.3);
}

.desk-top {
  width: 100%;
  height: 18px;
  background-color: var(--desk-top);
  border: 2px solid var(--desk-wood-dark);
  display: flex;
  align-items: center;
  justify-content: center;
}

.desk-id-label {
  font-size: 11px;
  color: var(--desk-wood-dark);
  font-weight: bold;
}

.student-tag {
  font-size: 14px;
  font-weight: bold;
  word-break: break-all;
  text-align: center;
  max-width: 100%;
  line-height: 1.2;
  margin-top: 4px;
}

.desk-cell.empty .student-tag {
  color: #6d4b29;
  font-style: italic;
  font-weight: normal;
  font-size: 12px;
}

.desk-cell.occupied {
  background-color: var(--occupied-bg);
  border-color: var(--occupied-border);
}

.desk-cell.occupied .desk-top {
  background-color: var(--occupied-top);
  border-color: var(--occupied-border);
}

.desk-cell.occupied .desk-id-label {
  color: var(--occupied-border);
}

.desk-cell.occupied .student-tag {
  color: #173314;
}

@media (max-width: 480px) {
  .classroom-card {
    padding: 16px;
  }

  .grid-container {
    gap: 8px;
  }

  .desk-cell {
    min-height: 72px;
    padding: 4px;
  }

  .title {
    font-size: 20px;
  }

  .counter-text {
    font-size: 18px;
  }

  .student-tag {
    font-size: 12px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_DESKS = 12;
  const ROWS = 3;
  const COLS = 4;

  // State: Array of 12 seats, null when empty, string student name when occupied
  const seats = Array(TOTAL_DESKS).fill(null);

  const deskGrid = document.getElementById('desk-grid');
  const counterDisplay = document.getElementById('counter');
  const nameInput = document.getElementById('student-name-input');
  const statusHint = document.getElementById('status-hint');

  function updateCounter() {
    const filledCount = seats.filter(name => name !== null).length;
    counterDisplay.textContent = filledCount;
  }

  function renderDesk(index) {
    const deskButton = document.getElementById(`desk-${index}`);
    if (!deskButton) return;

    const student = seats[index];
    const deskLabel = deskButton.querySelector('.student-tag');

    if (student !== null) {
      deskButton.classList.remove('empty');
      deskButton.classList.add('occupied');
      deskLabel.textContent = student;
      deskButton.setAttribute('aria-label', `Desk ${index + 1}: occupied by ${student}. Click to clear seat.`);
    } else {
      deskButton.classList.remove('occupied');
      deskButton.classList.add('empty');
      deskLabel.textContent = '[Empty]';
      deskButton.setAttribute('aria-label', `Desk ${index + 1}: empty. Click to seat student.`);
    }
  }

  function handleDeskClick(index) {
    const isOccupied = seats[index] !== null;

    if (isOccupied) {
      const previousStudent = seats[index];
      seats[index] = null;
      renderDesk(index);
      updateCounter();
      statusHint.textContent = `Cleared seat at Desk ${index + 1} (${previousStudent} left).`;
    } else {
      const studentName = nameInput.value.trim();
      if (!studentName) {
        statusHint.textContent = 'Please type a student name first!';
        nameInput.focus();
        return;
      }
      seats[index] = studentName;
      nameInput.value = '';
      renderDesk(index);
      updateCounter();
      statusHint.textContent = `Seated ${studentName} at Desk ${index + 1}.`;
      nameInput.focus();
    }
  }

  function createDesks() {
    deskGrid.innerHTML = '';
    for (let i = 0; i < TOTAL_DESKS; i++) {
      const row = Math.floor(i / COLS) + 1;
      const col = (i % COLS) + 1;

      const button = document.createElement('button');
      button.type = 'button';
      button.id = `desk-${i}`;
      button.className = 'desk-cell empty';
      button.setAttribute('role', 'gridcell');
      button.setAttribute('aria-label', `Desk ${i + 1} (Row ${row}, Col ${col}): empty. Click to seat student.`);

      const deskTop = document.createElement('div');
      deskTop.className = 'desk-top';

      const deskId = document.createElement('span');
      deskId.className = 'desk-id-label';
      deskId.textContent = `R${row}C${col}`;
      deskTop.appendChild(deskId);

      const studentTag = document.createElement('span');
      studentTag.className = 'student-tag';
      studentTag.textContent = '[Empty]';

      button.appendChild(deskTop);
      button.appendChild(studentTag);

      button.addEventListener('click', () => handleDeskClick(i));
      deskGrid.appendChild(button);
    }
  }

  // Enter key within input places focus on the first available desk
  nameInput.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      const firstEmptyIndex = seats.findIndex(name => name === null);
      if (firstEmptyIndex !== -1) {
        const targetDesk = document.getElementById(`desk-${firstEmptyIndex}`);
        if (targetDesk) targetDesk.focus();
      }
    }
  });

  createDesks();
  updateCounter();
});
